fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    // length of original vector
    let orig_len = orig.len();

    // If original length is greater or equal target width, return unchanged clone
    if orig_len >= width as usize {
        // Return original directly as spec says "exactly the original sequence"
        return orig;
    }

    // Need to pad - new length is width
    let target_len = width as usize;

    // Number of fillchar to add at the front
    let fill_count = target_len - orig_len;

    // Initialize vector with fillchar
    let mut result = Vec::with_capacity(target_len);
    
    // Fill leading positions with fillchar
    for _ in 0..fill_count {
        result.push(fillchar);
    }

    // Append the original vector content as suffix
    result.extend(orig.into_iter());

    result
}